describe('Image Preview Before Submission', () => {
  beforeEach(() => {
    cy.visit('/upload-form');
  });

  it('should display image preview when user uploads an image file', () => {
    // Intercept the file upload API
    cy.intercept('POST', '/api/upload/image', {
      statusCode: 200,
      body: {
        url: 'https://example.com/uploads/preview.jpg',
        filename: 'preview.jpg',
        size: 102456,
        mimeType: 'image/jpeg'
      }
    }).as('uploadImage');

    // Find and upload image file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-image.jpg', { force: true });

    // Verify preview appears
    cy.get('[data-testid="preview-image"]').should('be.visible');
    cy.get('[data-testid="preview-image"]').should('contain', 'test-image.jpg');

    // Verify preview image is displayed
    cy.get('[data-testid="preview-image"]').should('have.attr', 'src');
    cy.get('[data-testid="preview-image"]').should('have.attr', 'alt', 'Test Image');

    // Verify file upload API was called
    cy.wait('@uploadImage');

    // Verify form is still visible
    cy.get('[data-testid="upload-form"]').should('be.visible');

    // Verify submit button is enabled
    cy.get('[data-testid="submit-button"]').should('be.enabled');
  });

  it('should not display preview when no file is selected', () => {
    // Intercept the file upload API
    cy.intercept('POST', '/api/upload/image', {
      statusCode: 200,
      body: {
        url: 'https://example.com/uploads/preview.jpg',
        filename: 'preview.jpg',
        size: 102456,
        mimeType: 'image/jpeg'
      }
    }).as('uploadImage');

    // Attempt to submit without selecting a file
    cy.get('[data-testid="submit-button"]').click();

    // Verify preview does not appear
    cy.get('[data-testid="preview-image"]').should('not.exist');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please select an image file to upload');

    // Verify form is still visible
    cy.get('[data-testid="upload-form"]').should('be.visible');

    // Verify submit button is disabled
    cy.get('[data-testid="submit-button"]').should('be.disabled');
  });
});
